/bin/zsh -lc "node - <<'NODE'
const fs=require('fs');
const dir='docs/acceptance/t2181-independent-exec-443d50bf';
const v=JSON.parse(fs.readFileSync("'`${dir}/evidence/verdict.json`,'"'utf8'));
const g=JSON.parse(fs.readFileSync("'`${dir}/evidence/api-org-graph.json`,'"'utf8'));
const agentAgent=g.graph.edges.filter(e=>String(e.source).startsWith('agent:')&&String(e.target).startsWith('agent:'));
const rels=[...new Set(g.graph.edges.map(e=>e.relation_type))].sort();
console.log({verdict:v.verdict, pass:v.results.every(r=>r.status==='PASS'), agentAgent:agentAgent.length, agentAgentSample:agentAgent.slice(0,3), rels});
NODE"

/bin/zsh -lc "{
  echo 'HEAD='"'$(git rev-parse HEAD)
  echo '"'BASE='"'$(cat docs/acceptance/t2181-independent-exec-443d50bf/raw/provenance.log | awk -F= '"'/"'^base=/{print $2}'"')
  echo 'AHEAD_COUNT='"'$(git rev-list --count $(awk -F= '"'/"'^base=/{print $2}'"' docs/acceptance/t2181-independent-exec-443d50bf/raw/provenance.log)..HEAD)
  echo 'REMOTE_EXECUTOR_REF='"'$(git ls-remote origin-push refs/heads/ac-exec/task-86616b05/exec-443d50bf | awk '"'{print "'$1}'"')
  echo 'STATUS_SHORT_START'
  git status --short
  echo 'STATUS_SHORT_END'
  echo 'PRODUCT_VERDICT='"'$(node -e '"'const v=require(\"./docs/acceptance/t2181-independent-exec-443d50bf/verdict.json\"); process.stdout.write(v.product_verdict)')
  echo 'REPORT_VERDICT_LINE='"'$(grep -m1 '"'"'^Verdict:'"' docs/acceptance/t2181-independent-exec-443d50bf/REPORT.md)
  echo 'CANDIDATE_PARENT='"'$(git show -s --format=%P 6074ea621f178889bcfca5adca8cf27c3ad174da)
  echo '"'CANDIDATE_REMOTE='"'$(git rev-parse origin/ac-exec/task-340201c6/exec-7a7d087b)
} | tee docs/acceptance/t2181-independent-exec-443d50bf/raw/delivery-preflight.log'
